func:
let state = flow.get("masterOperatorControlsState");
if (!state) {
    state = {
        masterOnline: "unknown",
        common: {},
        seal: {},
        otvod: {},
        devices: {},
        cmdSeq: 0,
        lastCmd: "—",
        lastUpdate: "ожидание данных"
    };
}

function hasOwn(obj, key) {
    return Object.prototype.hasOwnProperty.call(obj, key);
}

function safeObject(value) {
    return value && typeof value === "object" ? value : {};
}

function toBool(value) {
    if (value === true || value === false) return value;
    const text = String(value ?? "").trim().toLowerCase();
    if (["true", "1", "yes", "online", "active"].includes(text)) return true;
    if (["false", "0", "no", "offline", "inactive"].includes(text)) return false;
    return null;
}

function toBoolWithDefault(value, fallback) {
    const parsed = toBool(value);
    return parsed === null ? fallback : parsed;
}

function toNumber(value, fallback = 0) {
    const num = Number(value);
    return Number.isFinite(num) ? num : fallback;
}

function normalizeMasterState(value) {
    const parsed = toBool(value);
    if (parsed === true) return "online";
    if (parsed === false) return "offline";

    const text = String(value ?? "").trim().toLowerCase();
    if (text === "online") return "online";
    if (text === "offline") return "offline";
    return "unknown";
}

function stageText(stage) {
    const key = String(stage || "idle");
    if (key === "wait_initial_batch") return "собираем первый блок";
    if (key === "wait_manip_ready") return "ожидаем готовность манипулятора";
    if (key === "wait_manip_step7") return "манипулятор в рабочем цикле";
    if (key === "wait_next_batch") return "ожидаем следующий блок";
    return "ожидание";
}

function makeEntity(id, title, key, status, reason, hint) {
    return {
        id,
        title,
        key,
        status,
        reason,
        hint: hint || ""
    };
}

const payload = msg.payload;
if (payload && typeof payload === "object") {
    if (hasOwn(payload, "online")) {
        state.masterOnline = normalizeMasterState(payload.online);
    }

    if (payload.common_cycle && typeof payload.common_cycle === "object") {
        state.common = payload.common_cycle;
    }

    if (payload.seal && typeof payload.seal === "object") {
        state.seal = payload.seal;
    }

    if (payload.otvod_cycle && typeof payload.otvod_cycle === "object") {
        state.otvod = payload.otvod_cycle;
    }

    if (payload.devices && typeof payload.devices === "object") {
        state.devices = payload.devices;
    }

    if (hasOwn(payload, "cmd_seq")) {
        state.cmdSeq = toNumber(payload.cmd_seq, 0);
    }

    if (hasOwn(payload, "last_cmd")) {
        const cmd = String(payload.last_cmd || "").trim();
        state.lastCmd = cmd || "—";
    }
}

if (msg.topic !== "operator/init") {
    state.lastUpdate = new Date().toLocaleString("ru-RU", { hour12: false });
}

flow.set("masterOperatorControlsState", state);

const common = safeObject(state.common);
const seal = safeObject(state.seal);
const otvod = safeObject(state.otvod);
const devices = safeObject(state.devices);
const conveyor = safeObject(devices.conveyor);
const manip = safeObject(devices.manipulator);

const conveyorHasData = Object.keys(conveyor).length > 0;
const manipHasData = Object.keys(manip).length > 0;
const sealHasData = Object.keys(seal).length > 0;
const otvodHasData = Object.keys(otvod).length > 0;

const conveyorLinked = conveyorHasData && toBoolWithDefault(conveyor.online, false) &&
    (hasOwn(conveyor, "kind_ok") ? toBoolWithDefault(conveyor.kind_ok, false) : true);
const manipLinked = manipHasData && toBoolWithDefault(manip.online, false) &&
    (hasOwn(manip, "kind_ok") ? toBoolWithDefault(manip.kind_ok, false) : true);
const sealLinked = sealHasData && toBoolWithDefault(seal.online, false);
const outfeedLinked = (otvodHasData && toBoolWithDefault(otvod.online, false)) || conveyorLinked;

const manipBusy = toBoolWithDefault(manip.busy, false);
const manipAlarm = toBoolWithDefault(manip.alarm, false);
const manipReady = toBoolWithDefault(manip.work_start_ready, false);
const manipNeedsGripOpen = toBoolWithDefault(manip.needs_grip_open_only, false);

let manipEntity;
if (!manipHasData) {
    manipEntity = makeEntity("manipulator", "Манипулятор", "nodata", "Нет данных", "Нет снимка от манипулятора.", "");
} else if (!manipLinked) {
    manipEntity = makeEntity("manipulator", "Манипулятор", "offline", "Нет связи", "Нет устойчивой связи с манипулятором.", "");
} else if (manipAlarm) {
    manipEntity = makeEntity("manipulator", "Манипулятор", "alarm", "Авария", "На манипуляторе активна авария.", "");
} else if (manipBusy) {
    manipEntity = makeEntity("manipulator", "Манипулятор", "work", "Работает", "Выполняет рабочий цикл.", "");
} else if (manipReady) {
    manipEntity = makeEntity("manipulator", "Манипулятор", "ready", "Готов", "Готов к следующему запуску.", "");
} else {
    const reason = manipNeedsGripOpen
        ? "Нужно подготовить захват перед стартом."
        : "Ожидает условия для следующего цикла.";
    manipEntity = makeEntity("manipulator", "Манипулятор", "wait", "Ждет", reason, "");
}

const batchReady = conveyorLinked && toBoolWithDefault(conveyor.batch_ready, false);
const feedSideEmptyValid = conveyorLinked && toBoolWithDefault(conveyor.feed_side_empty_valid, false);
const feedSideEmptyStrict = feedSideEmptyValid && toBoolWithDefault(conveyor.feed_side_empty_strict, true);
const feedSideCollecting = feedSideEmptyValid && !feedSideEmptyStrict;
const infeedProgramActive = conveyorLinked && toNumber(conveyor.program_state, 0) > 0;
const infeedWorking = !batchReady && feedSideCollecting && infeedProgramActive;

let infeedEntity;
if (!conveyorHasData) {
    infeedEntity = makeEntity("infeed", "Подводящий блок", "nodata", "Нет данных", "Нет валидного снимка по подводящей стороне.", "");
} else if (!conveyorLinked) {
    infeedEntity = makeEntity("infeed", "Подводящий блок", "offline", "Нет связи", "Нет связи с конвейером подвода.", "");
} else if (batchReady) {
    infeedEntity = makeEntity("infeed", "Подводящий блок", "ready", "Готов", "Следующий блок уже собран.", "");
} else if (!feedSideEmptyValid) {
    infeedEntity = makeEntity("infeed", "Подводящий блок", "nodata", "Нет данных", "Нет достоверного снимка подводящей стороны.", "");
} else if (infeedWorking) {
    infeedEntity = makeEntity("infeed", "Подводящий блок", "work", "Работает", "Собирает следующий блок для COMMON.", "");
} else {
    const infeedWaitReason = feedSideCollecting
        ? "Подводящий блок частично набран, ждет продолжение цикла."
        : "Блок еще не готов, ожидает следующий набор.";
    infeedEntity = makeEntity("infeed", "Подводящий блок", "wait", "Ждет", infeedWaitReason, "");
}

const conveyorErrorWord = toNumber(conveyor.error_word, 0);
const recoveryByBit = (conveyorErrorWord & 4) !== 0;
const commonLastLower = String(common.last || "").toLowerCase();
const recoveryByText = commonLastLower.includes("manual recovery required");
const recoveryRequired = recoveryByBit || recoveryByText;

const sealBusy = toBoolWithDefault(seal.busy, false) || toBoolWithDefault(seal.start_out, false);
const sealDonePendingUnload = toBoolWithDefault(common.sealer_done_pending_unload, false);
const sealDone = toBoolWithDefault(seal.done, false);

let sealerEntity;
if (!sealHasData) {
    sealerEntity = makeEntity("sealer", "Запайщик", "nodata", "Нет данных", "Нет валидного снимка по запайщику.", "");
} else if (!sealLinked) {
    sealerEntity = makeEntity("sealer", "Запайщик", "offline", "Нет связи", "Нет связи с платой запайщика.", "");
} else if (recoveryRequired) {
    sealerEntity = makeEntity("sealer", "Запайщик", "recovery", "Требует восстановления", "Нужно восстановление перед продолжением производства.", "");
} else if (sealBusy) {
    sealerEntity = makeEntity("sealer", "Запайщик", "work", "Работает", "Идет цикл запайки.", "");
} else if (sealDonePendingUnload || (sealDone && !sealBusy)) {
    sealerEntity = makeEntity("sealer", "Запайщик", "wait", "Ждет", "Цикл завершен, ожидает выгрузку блока.", "");
} else {
    sealerEntity = makeEntity("sealer", "Запайщик", "ready", "Готов", "Свободен для следующего этапа.", "");
}

const outfeedReady = conveyorLinked && toBoolWithDefault(conveyor.outfeed_ready_for_batch, false);
const outfeedActive =
    (otvodHasData && toBoolWithDefault(otvod.active, false)) ||
    (otvodHasData && toBoolWithDefault(otvod.step2_active, false)) ||
    (otvodHasData && toBoolWithDefault(otvod.vfd_timed_run_active, false)) ||
    (conveyorLinked && toBoolWithDefault(conveyor.vfd_timed_run_active, false));
const outfeedHolding = !outfeedReady && (
    outfeedActive ||
    toBoolWithDefault(common.active, false) ||
    toBoolWithDefault(common.outfeed_seen_not_ready, false) ||
    sealDonePendingUnload
);

let outfeedEntity;
if (!otvodHasData && !conveyorHasData) {
    outfeedEntity = makeEntity("outfeed", "Отводящий блок", "nodata", "Нет данных", "Нет валидного снимка по отводу.", "");
} else if (!outfeedLinked) {
    outfeedEntity = makeEntity("outfeed", "Отводящий блок", "offline", "Нет связи", "Нет связи с конвейером отвода.", "");
} else if (outfeedReady) {
    outfeedEntity = makeEntity("outfeed", "Отводящий блок", "ready", "Готов", "Готов принять следующий блок COMMON.", "");
} else if (outfeedActive) {
    outfeedEntity = makeEntity("outfeed", "Отводящий блок", "work", "Работает", "Идет активный отвод блока.", "");
} else if (outfeedHolding) {
    outfeedEntity = makeEntity("outfeed", "Отводящий блок", "wait", "Ждет", "Пока не готов и удерживает продолжение COMMON.", "");
} else {
    outfeedEntity = makeEntity("outfeed", "Отводящий блок", "wait", "Ждет", "Ожидает следующую команду.", "");
}

const entities = [manipEntity, infeedEntity, sealerEntity, outfeedEntity];
const allReady = entities.every((entity) => entity.key === "ready");

const masterBadge = {
    key: state.masterOnline,
    text: state.masterOnline === "online"
        ? "Мастер на связи"
        : state.masterOnline === "offline"
            ? "Нет связи с мастером"
            : "Нет данных по мастеру"
};

let processText = "Линия в ожидании команды COMMON START.";
if (state.masterOnline === "offline") {
    processText = "Нет связи с мастером COM12.";
} else if (sealerEntity.key === "recovery") {
    processText = "Нужно восстановление запайщика перед продолжением COMMON.";
} else if (toBoolWithDefault(common.active, false) && toBoolWithDefault(common.pause, false)) {
    processText = "COMMON на паузе: выполняется безопасная остановка.";
} else if (toBoolWithDefault(common.active, false)) {
    processText = "COMMON выполняется: " + stageText(common.stage) + ".";
} else if (allReady) {
    processText = "Все сущности готовы к запуску COMMON START.";
}

msg.payload = {
    title: "Операторский экран COM12",
    subtitle: "Состояние линии в реальном времени",
    summary: {
        master: masterBadge,
        lastUpdate: state.lastUpdate,
        processText
    },
    entities,
    cmdSeq: state.cmdSeq,
    lastCmd: state.lastCmd
};

return msg;

