  padding: 10px 12px;
}

.operator-meta-box span {
  color: #5b7169;
  display: block;
  font-size: 0.82rem;
  margin-bottom: 4px;
}

.operator-entities-grid {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.operator-entity-title {
  font-size: 1.12rem;
  font-weight: 700;
  margin: 0;
}

.operator-entity-status {
  margin-top: 10px;
}

.operator-entity-reason {
  margin: 12px 0 0;
}

.operator-entity-hint {
  color: #5b7169;
  font-size: 0.86rem;
  margin-top: 8px;
}

.operator-status-chip {
  border: 1px solid transparent;
  border-radius: 999px;
  display: inline-block;
  font-weight: 700;
  padding: 6px 12px;
}

.operator-status-chip--online,
.operator-status-chip--ready {
  background: #e5f5eb;
  border-color: #b7ddc6;
  color: #0b7a53;
}

.operator-status-chip--work {
  background: #e8f1fb;
  border-color: #b7cee9;
  color: #145a96;
}

.operator-status-chip--wait {
  background: #f6f1e7;
  border-color: #dfcfad;
  color: #7f6530;
}

.operator-status-chip--offline,
.operator-status-chip--nodata {
  background: #f1efeb;
  border-color: #d4cdc2;
  color: #6a6256;
}

.operator-status-chip--alarm,
.operator-status-chip--recovery {
  background: #fdebea;
  border-color: #e6b7b3;
  color: #8f2420;
}
